create table wksp_dtesc.sgt_salas (
    id             number generated by default on null as identity minvalue 1 maxvalue 9999999999999999999999999999 increment by 1 cache
    20 noorder nocycle nokeep noscale not null enable,
    sitio_id       number not null enable,
    siglas         varchar2(50 byte),
    nombre         varchar2(4000 byte),
    creado_por     varchar2(255 byte),
    creado_el      timestamp(6),
    modificado_por varchar2(255 byte),
    modificado_el  timestamp(6)
);

alter table wksp_dtesc.sgt_salas
    add constraint sgt_salas_nombre_nn check ( nombre is not null ) enable;

alter table wksp_dtesc.sgt_salas
    add constraint sgt_salas_siglas_nn check ( siglas is not null ) enable;

alter table wksp_dtesc.sgt_salas add primary key ( id )
    using index enable;


